#pragma once

#include <cstdint>

// The chests inside the shrines. Each has a flag in the save, CDungeon_<actor>_<hash id>, set when it is
// opened; the game also keeps CompleteTreasure_DungeonNNN for "none left" (see ShrineFlags.h).
// The table is generated by tools/gen_shrine_chests.py.
namespace Data
{
    struct ShrineChestList
    {
        uint32_t locationHash; // the shrine, by its discovery flag (Location_DungeonNNN)
        uint16_t first;        // its chests are ShrineChestFlags[first] to [first + count - 1]
        uint16_t count;
    };

    extern const ShrineChestList ShrineChestLists[]; // sorted by locationHash
    extern const int ShrineChestListsCount;
    extern const uint32_t ShrineChestFlags[];
    extern const int ShrineChestFlagsCount;
}

namespace ShrineChests
{
    // The chests of a shrine, or nullptr when the shrine is not in the table.
    const Data::ShrineChestList* Find(uint32_t locationHash);

    // How many of them are in openedFlags, a sorted list of chest flags.
    int CountOpened(const Data::ShrineChestList& list, const uint32_t* openedFlags, int openedCount);
}
